// What an engine sprite is: a declarative spec of parts made of primitives with depth, in
// the materials of palette.ts, and (for creatures) a rig of keyframed actions. Specs are plain
// data (no functions), so they can be written by hand, generated by a helper (motion.ts) or
// loaded from JSON or YAML; validateSpec checks them. How to write one: tools/CLAUDE.md,
// "spritegen: el motor".
import { PALETTE } from "../palette.ts";
import type { WindMeta } from "../wind.ts";
import type { MaterialName } from "../palette.ts";
import type { Vec3 } from "./math.ts";
import { ACTIONS, DIRS8, LOOP, SIZES } from "./style.ts";
import type { ActionName, Dir, SizeName, Tone } from "./style.ts";

/** What every primitive can say about its look (on top of its part's). */
interface ShapeLook {
  /** Another material than the part's. */
  material?: MaterialName;
  /** Added to the light level before it picks a shade (+ lighter, - darker). */
  bias?: number;
}

/** A 2D outline: [u, v] points; see `axis` for which plane they are drawn in. */
export type Profile = readonly (readonly [number, number])[];

/** The engine's primitives (shapes.ts), in the part's frame (x east, y north, z up). */
export type ShapeSpec =
  | (ShapeLook & { type: "ellipsoid"; center?: Vec3; radii: Vec3 })
  | (ShapeLook & { type: "box"; min: Vec3; max: Vec3 })
  | (ShapeLook & { type: "cylinder"; a: Vec3; b: Vec3; radius: number })
  /** A limb, a neck, a tail, a horn: round ends, tapering from radius at a to radius2 at b. */
  | (ShapeLook & { type: "capsule"; a: Vec3; b: Vec3; radius: number; radius2?: number })
  /**
   * A profile swept along `axis` from `from` to `to`. Along y (default) the points are drawn
   * as seen from the front ([x, z]); along x, from the side ([y, z]); along z, from above
   * ([x, y]). `bulge` (0..1) rounds the shading of its caps.
   */
  | (ShapeLook & {
      type: "extrusion";
      points: Profile;
      axis?: "x" | "y" | "z";
      from: number;
      to: number;
      bulge?: number;
    })
  /** A thin card: an extrusion `thickness` deep (default 1) centred on `at` (default 0). */
  | (ShapeLook & {
      type: "polygon";
      points: Profile;
      axis?: "x" | "y" | "z";
      at?: number;
      thickness?: number;
      bulge?: number;
    });

/** A single pixel painted on the surface (an eye, a nostril, a berry), in the part's frame. */
export interface MarkSpec {
  at: Vec3;
  /** The shade of the material (default deep); glint = its light shade lightened. */
  tone?: Tone | "glint";
  material?: MaterialName;
}

/** Value noise in the part's frame (it moves with the part, so it never boils). */
export interface TextureSpec {
  /** Light levels it adds or takes away, at most (0.1 to 0.3 reads as fur or grain). */
  amount: number;
  /** Size of a noise cell along the part's x, y and z: long cells make strands. */
  cell: Vec3;
}

export interface PartSpec {
  name: string;
  /** The part it hangs from (declared before it). Roots hang from the model. */
  parent?: string;
  /** The joint: this part's origin in its parent's frame (the model's for a root). */
  at?: Vec3;
  /** Rest rotation, degrees about x, y and z (applied in that order). */
  rot?: Vec3;
  material: MaterialName;
  shapes: readonly ShapeSpec[];
  /** Added to the light level of all its shapes. */
  bias?: number;
  texture?: TextureSpec;
  /** Specular glint where the light reflects at the camera (eyes, wet noses, metal). */
  shiny?: boolean;
  /** Glows (fire): bright where it faces the camera, never in shadow, soft outline. */
  glow?: boolean;
  marks?: readonly MarkSpec[];
}

/** A part's offset from its rest pose in a keyframe: rotation (degrees) and translation. */
export interface JointPose {
  rot?: Vec3;
  move?: Vec3;
}

/**
 * One keyframe: `at` in 0..1 of the action (a looping action wraps from the last key to the
 * first), and the pose of the parts that move. "*" is the whole model, about its origin on
 * the ground (a bob, a lunge, a fall).
 */
export interface KeySpec {
  at: number;
  pose: Readonly<Record<string, JointPose>>;
}

export interface ActionSpec {
  /** Frames per facing (ANI-2 range in style.ts ACTIONS). */
  frames: number;
  /** Ms per frame (not for walk: it plays by distance). */
  ms?: number;
  keys: readonly KeySpec[];
  /** Facings to render (default all four). */
  dirs?: readonly Dir[];
  /**
   * Per facing, how far (degrees about the vertical axis, the way the facings turn) the
   * whole figure has turned by the last frame, a little more each frame from none at the
   * first. A person falling along the screen's depth is foreshortened into a lump: turned
   * as it falls, it lies across the tile and reads as a body.
   */
  turn?: Partial<Record<Dir, number>>;
}

/**
 * An animated prop's loop (ART-7, style.ts LOOP): `frames` frames of `ms` each, keyed like an
 * action (frame f at f/frames, wrapping from the last key to the first); `sync` is how the
 * map plays a row of them (world: in step; tile: each with its own phase; random).
 */
export interface LoopSpec {
  frames: number;
  ms: number;
  sync: (typeof LOOP.syncs)[number];
  keys: readonly KeySpec[];
}

export interface SpriteSpec {
  /** Atlas path: the sprite field of data/ (creatures/bristleback_boar). */
  sprite: string;
  /** ART-2 class (style.ts SIZES): canvas, anchor, value band and outline policy. */
  size: SizeName;
  /** One of the class's canvases (default its first). */
  canvas?: readonly [number, number];
  /** Narrower figure bounds than the class's (px, outline included), checked by the gates. */
  figure?: { height?: readonly [number, number]; width?: readonly [number, number] };
  parts: readonly PartSpec[];
  /** Creatures: the rig's actions (idle and walk at least). Objects: none (one image). */
  actions?: Partial<Record<ActionName, ActionSpec>>;
  /** Objects: an ART-7 loop (the sprite and <sprite>/frame_<n>) instead of one image. */
  loop?: LoopSpec;
  /** Extra turn of the model for a facing (degrees), to show a 3/4 rather than a pure view. */
  views?: Partial<Record<Dir, number>>;
  /** Hovers (assets/sprites.yaml `flying: true`): the client bobs it. */
  flying?: boolean;
  /** A plant object: how it takes the wind (../wind.ts plantWind, like Recipe.wind). */
  wind?: WindMeta;
  /** The ground its review lineup stands on (a ground sprite such as ground/ash; default grass). */
  seenOn?: string;
  /**
   * A paper-doll layer (docs/17 ART-2 "Humanoides del motor"): only the `draw` parts give
   * pixels; the `occlude` parts (default: every other part) are cast too and hide what is
   * behind them, but give no pixels, so the layer drawn over the body shows only where it
   * is in front of it. Parts in neither list are left out (a robe is not pierced by the legs
   * it hides).
   */
  layer?: { draw: readonly string[]; occlude?: readonly string[] };
  /**
   * Walk frames per tile walked (atlas.json `perTile`; spritepack's default is half the
   * frames). A humanoid derives it from its stride (specs/humanoid) so the planted foot
   * stays on its ground point while the body passes.
   */
  perTile?: number;
  /**
   * Walk frames per tile walked facing north or south: perTile over the depth foreshortening
   * of the 3/4 view (style.ts PROJECTION.depth). A tile is as tall on the map as it is wide,
   * but the model's depth shows at 0.58 a pixel per unit, so walking toward or away from the
   * camera the planted foot holds only when the cycle is that much longer on screen.
   */
  perTileNS?: number;
  /**
   * Packed cropped to the opaque box of each frame (assets/sprites.yaml `trim: true`): the
   * paper-doll frames, mostly empty 64x64 (docs/07 "Atlas").
   */
  trim?: boolean;
}

const SPRITE_PATH = /^[a-z0-9_]+(\/[a-z0-9_]+)+$/;
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const isVec = (v: unknown): v is Vec3 => Array.isArray(v) && v.length === 3 && v.every(isNum);

/** The materials a spec draws with (parts, shapes and marks). */
export function specMaterials(spec: SpriteSpec): Set<MaterialName> {
  const out = new Set<MaterialName>();
  for (const p of spec.parts) {
    out.add(p.material);
    for (const s of p.shapes) if (s.material) out.add(s.material);
    for (const m of p.marks ?? []) if (m.material) out.add(m.material);
  }
  return out;
}

/** Problems with a spec, as "<sprite>: <what>" lines (empty = valid). */
export function validateSpec(spec: SpriteSpec): string[] {
  const out: string[] = [];
  const bad = (msg: string): void => {
    out.push(`${spec.sprite}: ${msg}`);
  };
  if (!SPRITE_PATH.test(spec.sprite)) bad("sprite must be a lowercase path such as creatures/boar");
  const size = SIZES[spec.size] as (typeof SIZES)[SizeName] | undefined;
  if (!size) {
    bad(`size ${String(spec.size)} is not one of ${Object.keys(SIZES).join(", ")}`);
    return out;
  }
  const canvas = spec.canvas ?? size.canvases[0];
  if (!canvas || !size.canvases.some(([w, h]) => w === canvas[0] && h === canvas[1]))
    bad(`canvas ${String(canvas)} is not an ART-2 canvas of ${spec.size}`);
  const range = (name: string, r: readonly [number, number] | undefined): void => {
    if (r && !(isNum(r[0]) && isNum(r[1]) && r[0] > 0 && r[0] <= r[1]))
      bad(`figure.${name} must be [min, max] with 0 < min <= max`);
  };
  range("height", spec.figure?.height);
  range("width", spec.figure?.width);

  // Parts.
  const names = new Set<string>();
  const declared = new Set(spec.parts.map((p) => p.name));
  for (const n of [...(spec.layer?.draw ?? []), ...(spec.layer?.occlude ?? [])])
    if (!declared.has(n)) bad(`layer names part ${n}, which it does not have`);
  if (spec.layer && spec.layer.draw.length === 0) bad("layer.draw names no part");
  if (spec.perTile !== undefined && !(isNum(spec.perTile) && spec.perTile > 0))
    bad("perTile must be > 0");
  if (spec.perTileNS !== undefined && !(isNum(spec.perTileNS) && spec.perTileNS > 0))
    bad("perTileNS must be > 0");
  if (spec.parts.length === 0) bad("has no parts");
  for (const p of spec.parts) {
    const where = `part ${p.name}`;
    if (!/^[a-z][a-z0-9_]*$/.test(p.name)) bad(`${where}: name must be lowercase snake_case`);
    if (names.has(p.name)) bad(`${where}: declared twice`);
    if (p.parent !== undefined && !names.has(p.parent))
      bad(`${where}: parent ${p.parent} must be declared before it`);
    names.add(p.name);
    if (!(p.material in PALETTE)) bad(`${where}: material ${p.material} is not in palette.ts`);
    if (p.at !== undefined && !isVec(p.at)) bad(`${where}: at must be [x, y, z]`);
    if (p.rot !== undefined && !isVec(p.rot)) bad(`${where}: rot must be [x, y, z] degrees`);
    if (p.shapes.length === 0 && (p.marks ?? []).length === 0)
      bad(`${where}: has no shapes and no marks`);
    if (p.texture && !(isNum(p.texture.amount) && isVec(p.texture.cell)))
      bad(`${where}: texture needs amount and cell [x, y, z]`);
    if (p.texture && p.texture.cell.some((c) => c <= 0)) bad(`${where}: texture cells must be > 0`);
    if (p.glow && p.shiny) bad(`${where}: a glowing part cannot also be shiny`);
    for (const m of p.marks ?? []) {
      if (!isVec(m.at)) bad(`${where}: a mark needs at [x, y, z]`);
      if (m.material && !(m.material in PALETTE))
        bad(`${where}: mark material ${m.material} is not in palette.ts`);
    }
    p.shapes.forEach((s, i) => {
      for (const e of shapeProblems(s)) bad(`${where} shape ${i} (${s.type}): ${e}`);
    });
  }

  // Keys of an action or a loop: in order, in 0..1, moving parts that exist.
  const checkKeys = (where: string, keys: readonly KeySpec[]): void => {
    if (keys.length === 0) bad(`${where}: has no keys`);
    let last = -Infinity;
    for (const k of keys) {
      if (!isNum(k.at) || k.at < 0 || k.at > 1) bad(`${where}: key at ${k.at} is not in 0..1`);
      if (k.at < last) bad(`${where}: keys must go in order of at`);
      last = k.at;
      for (const [part, pose] of Object.entries(k.pose)) {
        if (part !== "*" && !names.has(part))
          bad(`${where}: key at ${k.at} moves unknown part ${part}`);
        if (pose.rot !== undefined && !isVec(pose.rot))
          bad(`${where}: ${part}.rot must be [x, y, z]`);
        if (pose.move !== undefined && !isVec(pose.move))
          bad(`${where}: ${part}.move must be [x, y, z]`);
      }
    }
  };

  // Actions.
  if (size.kind === "creature") {
    const actions = spec.actions ?? {};
    for (const need of ["idle", "walk"] as const)
      if (!actions[need]) bad(`a creature needs a ${need} action (ANI-2)`);
    for (const [name, a] of Object.entries(actions) as [ActionName, ActionSpec][]) {
      const rule = ACTIONS[name] as (typeof ACTIONS)[ActionName] | undefined;
      const where = `action ${name}`;
      if (!rule) {
        bad(`${where}: not an ANI-2 action (${Object.keys(ACTIONS).join(", ")})`);
        continue;
      }
      if (!Number.isInteger(a.frames) || a.frames < rule.frames[0] || a.frames > rule.frames[1])
        bad(`${where}: ${a.frames} frames, ANI-2 wants ${rule.frames[0]}-${rule.frames[1]}`);
      if (name === "walk") {
        if (a.ms !== undefined) bad(`${where}: walk plays by distance, no ms`);
      } else if (!isNum(a.ms) || a.ms <= 0) bad(`${where}: needs ms per frame`);
      else {
        if (rule.ms && (a.ms < rule.ms[0] || a.ms > rule.ms[1]))
          bad(`${where}: ${a.ms} ms per frame, ANI-2 wants ${rule.ms[0]}-${rule.ms[1]}`);
        const total = a.ms * a.frames;
        if (rule.total && (total < rule.total[0] || total > rule.total[1]))
          bad(`${where}: ${total} ms in all, ANI-2 wants ${rule.total[0]}-${rule.total[1]}`);
      }
      checkKeys(where, a.keys);
      for (const d of a.dirs ?? []) if (!DIRS8.includes(d)) bad(`${where}: dir ${d}`);
    }
  } else if (spec.actions && Object.keys(spec.actions).length > 0) {
    bad(`a ${spec.size} has no actions (only creatures are rigged)`);
  }

  // An animated prop's loop (ART-7).
  const loop = spec.loop;
  if (loop) {
    if (size.kind !== "object") bad("loop: only objects loop (a creature plays its actions)");
    const [f0, f1] = LOOP.frames;
    if (!Number.isInteger(loop.frames) || loop.frames < f0 || loop.frames > f1)
      bad(`loop: ${loop.frames} frames, ART-7 wants ${f0}-${f1}`);
    if (!isNum(loop.ms) || loop.ms < LOOP.ms[0] || loop.ms > LOOP.ms[1])
      bad(`loop: ${loop.ms} ms per frame, ART-7 wants ${LOOP.ms[0]}-${LOOP.ms[1]}`);
    if (!(LOOP.syncs as readonly string[]).includes(loop.sync))
      bad(`loop: sync ${String(loop.sync)} is not one of ${LOOP.syncs.join(", ")}`);
    checkKeys("loop", loop.keys);
  }
  return out;
}

function shapeProblems(s: ShapeSpec): string[] {
  const out: string[] = [];
  if (s.material !== undefined && !(s.material in PALETTE))
    out.push(`material ${s.material} is not in palette.ts`);
  switch (s.type) {
    case "ellipsoid":
      if (!isVec(s.radii) || s.radii.some((r) => r <= 0)) out.push("radii must be > 0");
      if (s.center !== undefined && !isVec(s.center)) out.push("center must be [x, y, z]");
      break;
    case "box":
      if (!isVec(s.min) || !isVec(s.max) || s.min.some((v, i) => v >= (s.max[i] ?? v)))
        out.push("min must be below max on every axis");
      break;
    case "cylinder":
    case "capsule":
      if (!isVec(s.a) || !isVec(s.b)) out.push("a and b must be [x, y, z]");
      if (!isNum(s.radius) || s.radius <= 0) out.push("radius must be > 0");
      if (s.type === "capsule" && s.radius2 !== undefined && !(isNum(s.radius2) && s.radius2 > 0))
        out.push("radius2 must be > 0");
      if (s.type === "cylinder" && isVec(s.a) && isVec(s.b) && s.a.every((v, i) => v === s.b[i]))
        out.push("a and b must differ");
      break;
    case "extrusion":
    case "polygon":
      if (s.points.length < 3) out.push("a profile needs 3 points or more");
      if (s.points.some((p) => p.length !== 2 || !p.every(isNum))) out.push("points are [u, v]");
      if (s.type === "extrusion" && !(isNum(s.from) && isNum(s.to) && s.from < s.to))
        out.push("from must be below to");
      if (s.type === "polygon" && s.thickness !== undefined && !(s.thickness > 0))
        out.push("thickness must be > 0");
      if (s.bulge !== undefined && !(s.bulge >= 0 && s.bulge <= 1)) out.push("bulge is 0..1");
      break;
  }
  return out;
}
